<script setup lang="ts">import{articles}from'~/data/site';useSeoMeta({title:'Actualités',description:'Les nouvelles, réflexions et temps forts de la communauté MIREF.'});const query=ref('');const category=ref('Toutes');const categories=['Toutes',...new Set(articles.map(a=>a.category))];const filtered=computed(()=>articles.filter(a=>(category.value==='Toutes'||a.category===category.value)&&(a.title+a.excerpt).toLowerCase().includes(query.value.toLowerCase())))</script>
<template><div><section class="page-hero purple-gradient"><div class="container-wide"><span class="eyebrow">Le journal MIREF</span><h1>Des nouvelles qui<br><em>nous rapprochent.</em></h1><p>Retrouvez les actualités, les réflexions bibliques et les histoires qui racontent la vie de notre communauté.</p></div></section><section class="section-space"><div class="container-wide"><div class="toolbar"><div><span class="eyebrow">À lire & à partager</span><h2 class="section-title">Le fil de la communauté.</h2></div><input v-model="query" class="form-field search" type="search" placeholder="Rechercher un article…" aria-label="Rechercher un article"></div><div class="filters"><button v-for="c in categories" :key="c" :class="{selected:category===c}" @click="category=c">{{c}}</button></div><div v-if="filtered.length" class="grid"><NewsCard v-for="a in filtered" :key="a.slug" :article="a"/></div><div v-else class="empty"><i class="pi pi-search"/><h3>Aucun article trouvé</h3><p>Essayez un autre mot-clé ou une autre catégorie.</p><button class="btn-light" @click="query='';category='Toutes'">Réinitialiser</button></div><p class="note">Les dates de publication et les articles définitifs seront renseignés par l’équipe de communication.</p></div></section></div></template>
